import Foundation
import Testing
@testable import SteerCore

// The daemon protocol shapes below follow the JSON schema generated by the installed CLI
// (`codex app-server generate-json-schema`, 0.145.0): `item/tool/requestUserInput` params,
// `ToolRequestUserInputResponse`, and `serverRequest/resolved`.

private let thread = UUID(uuidString: "01A09D9B-7642-7B51-BCCE-9B66CFE5361F")!
private let turn = UUID(uuidString: "01A09DB7-0C51-7F33-9EBC-4E44F91DF22C")!

private func requestMessage(id: Any = 41, thread: UUID = thread, item: String = "call_1",
                            questions: [[String: Any]]? = nil) -> [String: Any] {
    ["jsonrpc": "2.0", "id": id, "method": "item/tool/requestUserInput",
     "params": ["threadId": thread.uuidString.lowercased(), "turnId": turn.uuidString.lowercased(), "itemId": item,
                "questions": questions ?? [
                    ["id": "list_shape", "header": "List shape", "question": "Which?",
                     "options": [["label": "Nested levels (Recommended)", "description": "d"], ["label": "Same levels", "description": "d"]]],
                    ["id": "name", "header": "Name", "question": "Call it?", "options": NSNull(), "isOther": false]
                ]]]
}

private func rolloutQuestion(source: AttentionSource = .cli, callID: String = "call_1", session: UUID = thread) -> AttentionQuestion {
    AttentionQuestion(source: source, session: session, turn: turn, callID: callID, arrivedAt: 100,
                      prompts: [QuestionPrompt(id: "list_shape", header: "List shape", question: "Which?",
                                               options: ["Nested levels (Recommended)", "Same levels"]),
                                QuestionPrompt(id: "name", header: "Name", question: "Call it?", options: [])])
}

private func fullBook() -> (AppServerQuestionBook, AppServerQuestionRequest) {
    var book = AppServerQuestionBook()
    guard case let .request(request) = book.apply(message: requestMessage(), now: 100) else { fatalError("request expected") }
    return (book, request)
}

@Test func requestUserInputIsParsedByThreadItemAndQuestionId() {
    var book = AppServerQuestionBook()
    let event = book.apply(message: requestMessage(), now: 100)
    guard case let .request(request) = event else { Issue.record("expected a request"); return }
    #expect(request.requestID == .number(41))
    #expect(request.thread == thread && request.turn == turn && request.itemID == "call_1")
    #expect(request.questions.map(\.id) == ["list_shape", "name"])
    #expect(request.questions[0].options == ["Nested levels (Recommended)", "Same levels"])
    #expect(request.questions[1].options == nil)
    #expect(book.request(for: rolloutQuestion()) == request)
    // Identity is thread and item id, the same pair the rollout gives as session and call id.
    #expect(book.request(for: rolloutQuestion(callID: "call_2")) == nil)
    #expect(book.request(for: rolloutQuestion(session: UUID())) == nil)
    // The source label does not matter: a desktop thread on the daemon is answered the same way.
    #expect(book.request(for: rolloutQuestion(source: .desktop)) == request)
    // String request ids are kept as strings.
    var other = AppServerQuestionBook()
    guard case let .request(text) = other.apply(message: requestMessage(id: "req-7", item: "call_9"), now: 1) else { Issue.record("string id"); return }
    #expect(text.requestID == .text("req-7"))
}

@Test func malformedRequestsAreIgnoredAndNeverAnswerable() {
    var book = AppServerQuestionBook()
    let noID: [String: Any] = ["jsonrpc": "2.0", "method": "item/tool/requestUserInput",
                               "params": ["threadId": thread.uuidString, "turnId": turn.uuidString, "itemId": "c", "questions": []]]
    #expect(book.apply(message: noID, now: 1) == .ignored)
    var bad = requestMessage()
    bad["params"] = ["threadId": "not-a-uuid", "turnId": turn.uuidString, "itemId": "c", "questions": []]
    #expect(book.apply(message: bad, now: 1) == .ignored)
    #expect(book.apply(message: requestMessage(questions: [["id": "", "question": "q"]]), now: 1) == .ignored)
    #expect(book.apply(message: requestMessage(questions: [["header": "h", "question": "q"]]), now: 1) == .ignored)
    #expect(book.apply(message: requestMessage(questions: [["id": "a", "question": "q", "options": [["label": ""]]]]), now: 1) == .ignored)
    #expect(book.apply(message: ["jsonrpc": "2.0", "method": "turn/started", "params": ["threadId": "x"]], now: 1) == .other("turn/started"))
    #expect(book.apply(message: ["jsonrpc": "2.0", "id": 3, "result": [:]], now: 1) == .ignored)
    #expect(book.pendingCount == 0)
}

@Test func resolutionEvidenceDropsThePendingRequest() {
    let (fresh, request) = fullBook()
    let question = rolloutQuestion()
    // Another client answered: the daemon says so and Steer can no longer answer.
    var resolved = fresh
    #expect(resolved.apply(message: ["jsonrpc": "2.0", "method": "serverRequest/resolved",
                                     "params": ["requestId": 41, "threadId": thread.uuidString.lowercased()]], now: 2)
            == .resolved(thread: thread, requestID: .number(41)))
    #expect(resolved.request(for: question) == nil)
    // A resolution for another request leaves this one alone.
    var otherResolved = fresh
    _ = otherResolved.apply(message: ["jsonrpc": "2.0", "method": "serverRequest/resolved",
                                      "params": ["requestId": 40, "threadId": thread.uuidString]], now: 2)
    #expect(otherResolved.request(for: question) == request)
    // The turn ended or the thread closed: the pane is gone.
    var ended = fresh
    #expect(ended.apply(message: ["jsonrpc": "2.0", "method": "turn/completed",
                                  "params": ["threadId": thread.uuidString, "turn": ["id": turn.uuidString.lowercased()]]], now: 3)
            == .turnCompleted(thread: thread, turn: turn))
    #expect(ended.request(for: question) == nil)
    var closed = fresh
    _ = closed.apply(message: ["jsonrpc": "2.0", "method": "thread/closed", "params": ["threadId": thread.uuidString]], now: 3)
    #expect(closed.request(for: question) == nil)
    // Losing the connection loses every request: the request id belongs to that connection.
    var dropped = fresh
    dropped.disconnect()
    #expect(dropped.request(for: question) == nil && dropped.pendingCount == 0)
    // The same request arriving again after a reconnect is answerable again, unless Steer answered it.
    var again = dropped
    _ = again.apply(message: requestMessage(id: 5), now: 4)
    #expect(again.request(for: question)?.requestID == .number(5))
    var answered = fresh
    answered.markAnswered(request)
    #expect(answered.hasAnswered(question))
    answered.disconnect()
    _ = answered.apply(message: requestMessage(id: 6), now: 5)
    #expect(answered.request(for: question) == nil && answered.hasAnswered(question))
}

@Test func routeIsDaemonOnlyWhenItHoldsThePendingRequest() {
    let (book, request) = fullBook()
    let cli = rolloutQuestion()
    let desktop = rolloutQuestion(source: .desktop)
    #expect(QuestionAnswerRouting.route(for: cli, book: book, daemonConnected: true) == .daemon(request))
    #expect(QuestionAnswerRouting.route(for: desktop, book: book, daemonConnected: true) == .daemon(request))
    // Not connected, or the daemon never sent this request: the pre-daemon paths, unchanged.
    #expect(QuestionAnswerRouting.route(for: cli, book: book, daemonConnected: false) == .ghosttyRelay)
    #expect(QuestionAnswerRouting.route(for: desktop, book: book, daemonConnected: false) == .desktopPick)
    #expect(QuestionAnswerRouting.route(for: rolloutQuestion(callID: "call_2"), book: book, daemonConnected: true) == .ghosttyRelay)
    #expect(QuestionAnswerRouting.route(for: rolloutQuestion(source: .desktop, callID: "call_2"), book: book, daemonConnected: true) == .desktopPick)
    // Once Steer answered, the card stays on the daemon path (its status says so) rather than offering a key.
    var answered = book
    answered.markAnswered(request)
    #expect(QuestionAnswerRouting.route(for: cli, book: answered, daemonConnected: true) == .daemonAnswered)
    #expect(QuestionAnswerRouting.route(for: cli, book: answered, daemonConnected: false) == .daemonAnswered)
}

@Test func daemonPolicyAcceptsExactlyOneAnswerPerQuestionAndRefusesEverythingElse() {
    let (book, request) = fullBook()
    let question = rolloutQuestion()
    let fresh = QuestionAnswerProgress(call: question.id)
    typealias P = AppServerAnswerPolicy
    #expect(P.rejection(for: question, book: book, progress: fresh, question: 0, answer: .option(1)) == nil)
    #expect(P.rejection(for: nil, book: book, progress: fresh, question: 0, answer: .option(1)) == .notInQueue)
    #expect(P.rejection(for: rolloutQuestion(callID: "call_2"), book: book, progress: fresh, question: 0, answer: .option(1)) == .notInQueue)
    #expect(P.rejection(for: question, book: AppServerQuestionBook(), progress: fresh, question: 0, answer: .option(1)) == .noDaemonRequest)
    #expect(P.rejection(for: question, book: book, progress: fresh, question: 1, answer: .text("x")) == .wrongQuestion)
    #expect(P.rejection(for: question, book: book, progress: fresh, question: 0, answer: .option(2)) == .optionOutOfRange)
    #expect(P.rejection(for: question, book: book, progress: fresh, question: 0, answer: .option(-1)) == .optionOutOfRange)
    // A listed-options question takes an option, not typed text, unless Codex marked it isOther.
    #expect(P.rejection(for: question, book: book, progress: fresh, question: 0, answer: .text("typed")) == .textNotOffered)
    let second = fresh.recordingDraft(question: 0, answer: .option(0))
    #expect(second.questionIndex == 1 && second.phase == .ready && second.picks == [0: 0])
    #expect(P.rejection(for: question, book: book, progress: second, question: 1, answer: .text("Steer")) == nil)
    #expect(P.rejection(for: question, book: book, progress: second, question: 1, answer: .option(0)) == .notOfferable)
    #expect(P.rejection(for: question, book: book, progress: second, question: 1, answer: .text("   ")) == .emptyText)
    #expect(P.rejection(for: question, book: book, progress: second, question: 1,
                        answer: .text(String(repeating: "a", count: P.maximumText + 1))) == .textTooLong)
    #expect(P.rejection(for: question, book: book, progress: second, question: 0, answer: .option(1)) == nil)
    // Every non-ready phase refuses, and so does a question Steer already answered.
    let sending = second.startingSend(question: 1, option: 0)
    #expect(P.rejection(for: question, book: book, progress: sending, question: 1, answer: .text("x")) == .notReady)
    var answered = book
    answered.markAnswered(request)
    #expect(P.rejection(for: question, book: answered, progress: fresh, question: 0, answer: .option(0)) == .alreadyAnswered)
    // isOther: text or option; isSecret: nothing, the notch is not a private surface.
    var other = AppServerQuestionBook()
    _ = other.apply(message: requestMessage(questions: [["id": "q", "question": "?", "isOther": true,
                                                          "options": [["label": "a"], ["label": "b"]]]]), now: 1)
    let otherQuestion = AttentionQuestion(source: .cli, session: thread, turn: turn, callID: "call_1", arrivedAt: 1,
                                          prompts: [QuestionPrompt(id: "q", header: nil, question: "?", options: ["a", "b"], isOther: true)])
    #expect(P.rejection(for: otherQuestion, book: other, progress: QuestionAnswerProgress(call: otherQuestion.id), question: 0, answer: .text("c")) == nil)
    #expect(P.rejection(for: otherQuestion, book: other, progress: QuestionAnswerProgress(call: otherQuestion.id), question: 0, answer: .option(1)) == nil)
    var secret = AppServerQuestionBook()
    _ = secret.apply(message: requestMessage(questions: [["id": "q", "question": "token?", "isSecret": true]]), now: 1)
    #expect(P.rejection(for: otherQuestion, book: secret, progress: QuestionAnswerProgress(call: otherQuestion.id), question: 0, answer: .text("s")) == .secret)
    for rejection in [P.Rejection.notInQueue, .noDaemonRequest, .alreadyAnswered, .wrongQuestion, .notOfferable, .optionOutOfRange,
                      .textNotOffered, .emptyText, .textTooLong, .secret, .notReady] {
        #expect(!P.message(for: rejection).isEmpty)
    }
}

@Test func responseCarriesEveryQuestionsAnswerByIdAndOnlyWhenComplete() throws {
    let (_, request) = fullBook()
    let question = rolloutQuestion()
    let partial = QuestionAnswerProgress(call: question.id).recordingDraft(question: 0, answer: .option(1))
    #expect(AppServerAnswerPolicy.result(for: request, progress: partial) == nil)
    let complete = partial.recordingDraft(question: 1, answer: .text("  Steer  "))
    let result = try #require(AppServerAnswerPolicy.result(for: request, progress: complete))
    let answers = try #require(result["answers"] as? [String: [String: [String]]])
    // Option answers are the exact label Codex listed; typed answers are trimmed.
    #expect(answers == ["list_shape": ["answers": ["Same levels"]], "name": ["answers": ["Steer"]]])
    let message = request.responseMessage(result: result)
    #expect(message["jsonrpc"] as? String == "2.0")
    #expect(message["id"] as? Int == 41)
    #expect(JSONSerialization.isValidJSONObject(message))
    // A draft with an option beyond the request's list yields nothing rather than a guess.
    let stale = QuestionAnswerProgress(call: question.id).recordingDraft(question: 0, answer: .option(9)).recordingDraft(question: 1, answer: .text("x"))
    #expect(AppServerAnswerPolicy.result(for: request, progress: stale) == nil)
}

/// A fake client: records every message Steer would write, never answers back.
private final class FakeClient {
    var sent: [[String: Any]] = []
}

@Test func steerAnswersByCallIdExactlyOnceAndNeverOnUncertainty() throws {
    let (book, request) = fullBook()
    let question = rolloutQuestion()
    let client = FakeClient()
    // First question: only a draft; nothing leaves Steer.
    let first = AppServerAnswering.prepare(current: question, book: book, progress: QuestionAnswerProgress(call: question.id),
                                           question: 0, answer: .option(0), stillPending: { true }, now: 10)
    guard case let .drafted(progress1) = first.outcome else { Issue.record("draft expected"); return }
    #expect(first.message == nil && first.book == book)
    // Last question: one message, the request marked answered before anything is written.
    let last = AppServerAnswering.prepare(current: question, book: first.book, progress: progress1,
                                          question: 1, answer: .text("Steer"), stillPending: { true }, now: 11)
    guard case let .sending(progress2) = last.outcome else { Issue.record("send expected, got \(last.outcome)"); return }
    #expect(progress2.phase == .sending)
    let message = try #require(last.message)
    client.sent.append(message)
    #expect(message["id"] as? Int == 41)
    #expect((message["result"] as? [String: Any])?["answers"] as? [String: [String: [String]]]
            == ["list_shape": ["answers": ["Nested levels (Recommended)"]], "name": ["answers": ["Steer"]]])
    #expect(last.book.hasAnswered(question) && last.book.request(for: question) == nil)
    // Delivered: waits for the rollout to record it; nothing more is ever sent for this call.
    let delivered = progress2.recordingSent(question: 1, answer: .text("Steer"), of: question, at: 12)
    #expect(delivered.phase == .sent(at: 12) && delivered.texts == [1: "Steer"] && delivered.picks == [0: 0])
    let again = AppServerAnswering.prepare(current: question, book: last.book, progress: delivered,
                                           question: 1, answer: .text("Steer"), stillPending: { true }, now: 13)
    #expect(again.outcome == .refused(.alreadyAnswered) && again.message == nil)
    // A failed write is final too: Steer does not know whether the daemon read it.
    let failed = progress2.recordingFailure("write failed")
    let afterFailure = AppServerAnswering.prepare(current: question, book: last.book, progress: failed,
                                                  question: 1, answer: .text("Steer"), stillPending: { true }, now: 14)
    #expect(afterFailure.outcome == .refused(.alreadyAnswered) && afterFailure.message == nil)
    #expect(client.sent.count == 1)
    // Rollout says answered or ended, or unreadable: nothing is sent and the request stays unanswered by Steer.
    let guarded = AppServerAnswering.prepare(current: question, book: book, progress: progress1,
                                             question: 1, answer: .text("Steer"), stillPending: { false }, now: 15)
    #expect(guarded.outcome == .refused(.notPendingInRollout) && guarded.message == nil && guarded.book == book)
    // Resolved by another client before the click: refused, nothing sent.
    var resolved = book
    _ = resolved.apply(message: ["jsonrpc": "2.0", "method": "serverRequest/resolved",
                                 "params": ["requestId": 41, "threadId": thread.uuidString]], now: 9)
    let late = AppServerAnswering.prepare(current: question, book: resolved, progress: progress1,
                                          question: 1, answer: .text("Steer"), stillPending: { true }, now: 16)
    #expect(late.outcome == .refused(.noDaemonRequest) && late.message == nil)
    // Gone from the queue: refused.
    let gone = AppServerAnswering.prepare(current: nil, book: book, progress: progress1,
                                          question: 1, answer: .text("Steer"), stillPending: { true }, now: 17)
    #expect(gone.outcome == .refused(.notInQueue) && gone.message == nil)
    _ = request
}

