@Test func aClosedThreadForgetsItsAnsweredCallsAndAPickBeforeTheDaemonStartsOver() {
    let (book, request) = fullBook()
    let question = rolloutQuestion()
    var answered = book
    answered.markAnswered(request)
    _ = answered.apply(message: ["jsonrpc": "2.0", "method": "thread/closed", "params": ["threadId": thread.uuidString]], now: 3)
    #expect(!answered.hasAnswered(question))
    // The same call id on another thread is untouched.
    var other = book
    other.markAnswered(request)
    _ = other.apply(message: ["jsonrpc": "2.0", "method": "thread/closed", "params": ["threadId": UUID().uuidString]], now: 3)
    #expect(other.hasAnswered(question))
    // A desktop pick made before the daemon held the request only opened Codex; the daemon card restarts.
    let picked = QuestionAnswerProgress(call: question.id).pickingInCodex(question: 0, option: 1)
    let reopened = picked.reopeningForDaemon()
    #expect(reopened.phase == .ready && reopened.picks.isEmpty && reopened.questionIndex == 0)
    let drafted = QuestionAnswerProgress(call: question.id).recordingDraft(question: 0, answer: .text("x"))
    #expect(drafted.reopeningForDaemon() == drafted)
    // A typed last answer moves to sending without a placeholder option.
    #expect(drafted.startingSend(question: 1).phase == .sending)
    #expect(drafted.startingSend(question: 0).phase == .ready)
}

// MARK: - Symlinked control socket (Codex 0.161)

/// Binds a Unix socket at `path` and returns its descriptor (closed by the caller).
private func bindSocket(_ path: String) throws -> Int32 {
    let fd = socket(AF_UNIX, SOCK_STREAM, 0)
    var address = sockaddr_un()
    address.sun_family = sa_family_t(AF_UNIX)
    let bytes = Array(path.utf8)
    try #require(bytes.count < MemoryLayout.size(ofValue: address.sun_path))
    withUnsafeMutableBytes(of: &address.sun_path) { raw in
        raw.copyBytes(from: bytes)
        raw[bytes.count] = 0
    }
    let result = withUnsafePointer(to: &address) {
        $0.withMemoryRebound(to: sockaddr.self, capacity: 1) { bind(fd, $0, socklen_t(MemoryLayout<sockaddr_un>.size)) }
    }
    try #require(result == 0)
    return fd
}

@Test func appServerSocketCheckFollowsOnePrivateSymlink() throws {
    // Short paths: Unix socket paths are limited to about 104 bytes.
    let root = "/tmp/st-\(UUID().uuidString.prefix(8))"
    let fm = FileManager.default
    try fm.createDirectory(atPath: root + "/d", withIntermediateDirectories: true, attributes: [.posixPermissions: 0o700])
    try fm.createDirectory(atPath: root + "/c", withIntermediateDirectories: true, attributes: [.posixPermissions: 0o700])
    defer { try? fm.removeItem(atPath: root) }
    let target = root + "/d/s"
    let fd = try bindSocket(target)
    defer { close(fd) }
    chmod(target, 0o600)
    let link = root + "/c/control.sock"
    try fm.createSymbolicLink(atPath: link, withDestinationPath: target)

    // Codex 0.161's layout: a link owned by the user to a private socket in a private directory.
    #expect(AppServerSocketCheck.problem(at: link, followsPrivateLink: true) == nil)
    #expect(AppServerSocketCheck.problem(at: target) == nil)
    // Only the Codex daemon follows the link: herdr's socket must be a socket file itself (ADR 0009).
    #expect(AppServerSocketCheck.problem(at: link) == .notASocket)
    #expect(HerdrSocketTrust.reason(at: link) == .untrustedSocket)
    #expect(HerdrSocketTrust.reason(at: target) == nil)

    // The target's directory open to others: another user could substitute the socket.
    chmod(root + "/d", 0o755)
    #expect(AppServerSocketCheck.problem(at: link, followsPrivateLink: true) == .sharedPermissions)
    chmod(root + "/d", 0o700)

    // A relative target, a second link, a regular file, or a missing target is refused.
    try fm.removeItem(atPath: link)
    try fm.createSymbolicLink(atPath: link, withDestinationPath: "../d/s")
    #expect(AppServerSocketCheck.problem(at: link, followsPrivateLink: true) == .notASocket)
    try fm.removeItem(atPath: link)
    try fm.createSymbolicLink(atPath: root + "/d/hop", withDestinationPath: target)
    try fm.createSymbolicLink(atPath: link, withDestinationPath: root + "/d/hop")
    #expect(AppServerSocketCheck.problem(at: link, followsPrivateLink: true) == .notASocket)
    try fm.removeItem(atPath: link)
    fm.createFile(atPath: root + "/d/file", contents: Data(), attributes: [.posixPermissions: 0o600])
    try fm.createSymbolicLink(atPath: link, withDestinationPath: root + "/d/file")
    #expect(AppServerSocketCheck.problem(at: link, followsPrivateLink: true) == .notASocket)
    try fm.removeItem(atPath: link)
    try fm.createSymbolicLink(atPath: link, withDestinationPath: root + "/d/missing")
    #expect(AppServerSocketCheck.problem(at: link, followsPrivateLink: true) == .missing)

    // A shared socket behind a private link is still refused.
    try fm.removeItem(atPath: link)
    try fm.createSymbolicLink(atPath: link, withDestinationPath: target)
    chmod(target, 0o666)
    #expect(AppServerSocketCheck.problem(at: link, followsPrivateLink: true) == .sharedPermissions)
}

@Test func daemonDraftEditsPreservePositionAndSubmitOnlyTheReplacement() throws {
    let (book, _) = fullBook()
    let question = rolloutQuestion()
    let first = AppServerAnswering.prepare(current: question, book: book, progress: QuestionAnswerProgress(call: question.id),
                                           question: 0, answer: .option(0), stillPending: { true }, now: 1)
    guard case let .drafted(draft) = first.outcome else { Issue.record("Expected draft"); return }
    let edit = AppServerAnswering.prepare(current: question, book: book, progress: draft,
                                          question: 0, answer: .option(1), stillPending: { true }, now: 2)
    guard case let .drafted(changed) = edit.outcome else { Issue.record("Expected replacement draft"); return }
    #expect(edit.message == nil && !edit.book.hasAnswered(question))
    #expect(changed.questionIndex == 1 && changed.answer(for: 0) == .option(1))
    let final = AppServerAnswering.prepare(current: question, book: edit.book, progress: changed,
                                           question: 1, answer: .text("Steer"), stillPending: { true }, now: 3)
    let result = try #require(final.message?["result"] as? [String: Any])
    let answers = try #require(result["answers"] as? [String: [String: [String]]])
    #expect(answers["list_shape"]?["answers"] == ["Same levels"])
    #expect(answers["name"]?["answers"] == ["Steer"])
    #expect(final.book.hasAnswered(question))
    let duplicate = AppServerAnswering.prepare(current: question, book: final.book, progress: changed,
                                               question: 0, answer: .option(0), stillPending: { true }, now: 4)
    #expect(duplicate.outcome == .refused(.alreadyAnswered) && duplicate.message == nil)
}

@Test func daemonDraftReplacementClearsTheOtherAnswerKindAndPreservesOtherDrafts() {
    let question = rolloutQuestion()
    let draft = QuestionAnswerProgress(call: question.id).recordingDraft(question: 0, answer: .option(0))
        .recordingDraft(question: 1, answer: .text("Keep this"))
    let typed = draft.replacingDraft(question: 0, answer: .text("New answer"))
    #expect(typed.picks[0] == nil && typed.answer(for: 0) == .text("New answer"))
    #expect(typed.answer(for: 1) == .text("Keep this") && typed.questionIndex == 2)
    let option = typed.replacingDraft(question: 0, answer: .option(1))
    #expect(option.texts[0] == nil && option.answer(for: 0) == .option(1))
    #expect(option.replacingDraft(question: -1, answer: .text("x")) == option)
    #expect(option.replacingDraft(question: 2, answer: .text("x")) == option)
}

@Test func daemonDraftEditsRefuseStaleDisconnectedAndSendingRequests() {
    let (book, _) = fullBook()
    let question = rolloutQuestion()
    let draft = QuestionAnswerProgress(call: question.id).recordingDraft(question: 0, answer: .option(0))
    let stale = AppServerAnswering.prepare(current: question, book: book, progress: draft,
                                           question: 0, answer: .option(1), stillPending: { false }, now: 2)
    #expect(stale.outcome == .refused(.notPendingInRollout) && stale.message == nil)
    var disconnected = book
    disconnected.disconnect()
    #expect(AppServerAnswerPolicy.rejection(for: question, book: disconnected, progress: draft,
                                            question: 0, answer: .option(1)) == .noDaemonRequest)
    let sending = draft.startingSend(question: 1)
    #expect(AppServerAnswerPolicy.rejection(for: question, book: book, progress: sending,
                                            question: 0, answer: .option(1)) == .notReady)
    #expect(sending.replacingDraft(question: 0, answer: .option(1)) == sending)
    let otherTurn = AttentionQuestion(source: question.source, session: question.session, turn: UUID(),
                                      callID: question.callID, arrivedAt: 1, prompts: question.prompts)
    #expect(book.request(for: otherTurn) == nil)
    #expect(AppServerAnswerPolicy.rejection(for: rolloutQuestion(session: UUID()), book: book, progress: draft,
                                            question: 0, answer: .option(1)) == .notInQueue)
    // Terminal policies still refuse the earlier index, even though the daemon permits draft edits.
    #expect(QuestionAnswerPolicy.rejection(for: question, ghosttyEnabled: true, progress: draft,
                                           question: 0, option: 1) == .wrongQuestion)
}
